In this paper, we study the Scholtes-type regularization method for the class of cardinality-constrained optimization problems:
\[
\mbox{CCOP}: \quad
\min_{x} \,\, f(x)\quad \mbox{s.\,t.} \quad h(x)=0, \quad g(x)\ge 0, \quad \left\|x\right\|_0\le s
\]
with the feasible set given by equality, inequality, and cardinality constraints, where the so-called zero ”norm” $\left\|x\right\|_0 = \left\vert \left\{i \in \{1,\ldots, n\}\; \vert\; x_i\ne 0\right\}\right\vert$ is counting non-zero entries of $x$.
Here, we assume that the objective function $f$, as well as the equality and inequality constraints 
$h=\left(h_p, p \in P\right)$,
$g=\left(g_q, q \in Q\right)$ are twice continuously differentiable, and $s \in \{0,1,\ldots, n-1\}$ is an integer. 


Our notation is standard. The cardinality of a finite set $A$ is denoted by $\vert A \vert$. The $n$-dimensional Euclidean space is denoted by $\mathbb{R}^n$ with the coordinate vectors $e_i,i= 1,\ldots, n$. The vector consisting of ones is denoted by $e$. Given a twice continuously differentiable function $f:\mathbb{R}^n\rightarrow \mathbb{R}$, $\nabla f$ denotes its gradient, and $D^2f$ stands for its Hessian.


We associate with CCOP the regularized continuous reformulation from \cite{laemmel:reform}:
\[
     \begin{array}{rl}
    \displaystyle \mathcal{R}(c,\varepsilon): \quad \min_{x,y} \,\, f(x) +c^Ty\quad \mbox{s.\,t.} 
   &h(x)=0, \quad g(x)\ge 0, \quad \displaystyle \sum_{i=1}^{n} y_i \geq  n - s, \quad \\
   &x_i y_i =0, \quad 0 \leq y_i \leq 1+\varepsilon,  \quad i=1, \ldots, n,
   \end{array}
\]
where the components of $c \in \R^n$ $c$ are positive and pairwise different, and $0 < \varepsilon \leq \frac{1}{n-s}$.
Given a feasible point  $(\bar x,\bar y)$ of $\mathcal{R}$, we define the index sets which correspond to the orthogonality type constraints $x_i y_i=0$, $y_i \geq 0$:
    \[
     \begin{array}{c}
        a_{01}\left(\bar x,\bar y\right)=\left\{i\,\left\vert\, \bar x_i=0,\bar y_i>0\right.\right\}, \quad 
    a_{10}\left(\bar x,\bar y\right)=\left\{i\,\left\vert\, \bar x_i\ne 0,\bar y_i=0\right.\right\}, \\
    a_{00}\left(\bar x,\bar y\right)=\left\{i\,\left\vert\, \bar x_i=0,\bar y_i=0\right.\right\}.       
     \end{array}
    \]
%The $y$-components which attain the upper bound are stored in  
%     \[\mathcal{E}(\bar y)=\left\{i \in\{1,\ldots,n\}\left\vert\,\bar y_i=1+\varepsilon\right.\right\}.\]
The index sets of the active inequality constraints will be denoted by
\[
 Q_0(\bar x)=\left\{q \in Q \, \left\vert\, g_q(\bar x)=0\right.\right\}, \quad\mathcal{E}(\bar y)=\left\{i \,\left\vert\,\bar y_i=1+\varepsilon\right.\right\}.
\]


\begin{definition}[MPOC-LICQ, \cite{laemmel:reform}]
We say that a feasible point $(\bar x,\bar y)$ of $\mathcal{R}$ satisfies the MPOC-tailored linear independence constraint qualification (MPOC-LICQ) if the following vectors are linearly independent:
\[
\begin{array}{c}
\begin{pmatrix}
\nabla h_p(\bar x)\\0
\end{pmatrix}, p \in P, \quad 
\begin{pmatrix}
\nabla g_q(\bar x)\\0
\end{pmatrix}, q \in Q_0(\bar x), \quad  
\begin{pmatrix}
0\\
e_i
\end{pmatrix},i\in \mathcal{E}(\bar y), \quad
\begin{pmatrix}
0\\
e
\end{pmatrix}
\mbox{ if } \sum\limits_{i=1}^{n} \bar y_i = n - s,
\\
\begin{pmatrix}
e_i\\
0
\end{pmatrix}, i \in a_{01}\left(\bar x,\bar y\right)\cup a_{00}\left(\bar x,\bar y\right), \quad 
\begin{pmatrix}
0\\
e_i
\end{pmatrix}, i \in a_{10}\left(\bar x, \bar y\right)\cup a_{00}\left(\bar x, \bar y\right).
\end{array}
\]
\end{definition}

\begin{definition}[T-stationary point, \cite{laemmel:reform}]
\label{def:t-stat}
A feasible point $(\bar x,\bar y)$ of $\mathcal{R}$ is called T-stationary if there exists multipliers 
\[
\begin{array}{l}
\bar \lambda_p, p \in P,
\bar \mu_{1,q}, q\in Q_0(\bar x),\bar \mu_{2,i},i \in \mathcal{E}(\bar y),\bar \mu_3,\\ \bar \sigma_{1,i}, i \in a_{01}\left(\bar x,\bar y\right),\bar \sigma_{2,i}, i \in a_{10}\left(\bar x,\bar y\right),\bar \varrho_{1,i},\bar \varrho_{2,i}, i \in a_{00}\left(\bar x, \bar y\right),
\end{array}
\]
such that the following conditions hold:
\begin{equation}
   \label{eq:tstat-1} 
   \begin{array}{rcl}
  \begin{pmatrix}
   \nabla f(\bar x)\\
   c
  \end{pmatrix}&=& \displaystyle\sum\limits_{p \in P}\bar \lambda_p 
  \begin{pmatrix}
  \nabla h_p(\bar x)\\
  0
  \end{pmatrix}+
    \sum\limits_{q \in Q_0(\bar x)}\bar \mu_{1,q} 
    \begin{pmatrix}
    \nabla g_q(\bar x)\\
    0
    \end{pmatrix}-
    \sum\limits_{i\in\mathcal{E}(\bar y)} \bar \mu_{2,i} \begin{pmatrix}
    0\\
    e_i
\end{pmatrix}\\ 
    && +
\bar \mu_3 \begin{pmatrix}
0\\
e
\end{pmatrix}\displaystyle +\sum\limits_{i \in a_{01}\left(\bar x,\bar y\right)} \bar \sigma_{1,i}
    \begin{pmatrix}
    e_{ i}\\
    0
    \end{pmatrix}
    +\sum\limits_{i \in a_{10}\left(\bar x,\bar y \right)} \bar \sigma_{2,i}    \begin{pmatrix}
    0\\
    e_{ i}
    \end{pmatrix}\\ 
    &&\displaystyle+\sum\limits_{i \in a_{00}\left(\bar x, \bar y\right)} \left(\bar \varrho_{1,i}
    \begin{pmatrix}
   e_{ i}\\
    0
    \end{pmatrix}
   +\bar \varrho_{2,i}
    \begin{pmatrix}
    0\\
    e_{ i}
    \end{pmatrix}\right), \end{array}
\end{equation}
\begin{equation}
   \label{eq:tstat-2} \bar \mu_{1,q} \ge 0,q\in Q_0\left(\bar x\right),
   \bar \mu_{2,i} \ge 0, i\in \mathcal{E}(\bar y),\bar \mu_3\ge 0, \bar\mu_3\left(
   \sum\limits_{i=1}^{n} \bar y_i -(n-s)\right)=0,
\end{equation}
\begin{equation}
   \label{eq:tstat-3} \bar \varrho_{1,i}=0 \mbox{ or }\bar \varrho_{2,i}\le 0, i \in a_{00}\left(\bar x,\bar y\right).
\end{equation}
\end{definition}

We define the appropriate Lagrange function:
\[
        \begin{array}{rcl}
        L^\mathcal{R}(x,y)&=& \displaystyle
   f(x)+
   c^T y -
        \sum\limits_{p \in P}\bar \lambda_p
  h_p( x)-
    \sum\limits_{q \in Q_0(\bar x)}\bar \mu_{1,q} 
    g_q(x) \\  & &\displaystyle+\sum\limits_{i\in\mathcal{E}(\bar y)} \bar \mu_{2,i} 
   \left( y_i- (1+\varepsilon)\right)
-
\bar \mu_3 
 \left(\sum\limits_{i=1}^{n} y_i - (n-s)\right)
   \\ 
    &&\displaystyle -\sum\limits_{i \in a_{01}\left(\bar x, \bar y\right)} \bar \sigma_{1,i}
     x_{ i}
    -\sum\limits_{i \in a_{10}\left(\bar x, \bar y\right)} \bar \sigma_{2,i}   
     y_{ i} -\sum\limits_{i \in a_{00}\left(\bar x, \bar y \right)} \left(\bar \varrho_{1,i}
    x_{ i}
   +\bar \varrho_{2,i}
     y_{ i}
    \right).
    \end{array}
\]
Moreover, we set for the corresponding tangent space:

\[
    \mathcal{T}^{\mathcal{R}}_{(\bar x,\bar y)} =\left\{
\xi \in \R^{2n}\,\left\vert\, \begin{array}{l} \begin{pmatrix}
Dh_p(\bar x), 0\end{pmatrix} \xi=0, p \in P, 
\begin{pmatrix}
Dg_q(\bar x), 0\end{pmatrix}\xi=0,q \in Q_0(\bar x),\\
\begin{pmatrix}
0,e_i
\end{pmatrix}\xi=0, i\in \mathcal{E}(\bar y), 
\begin{pmatrix}
0,e
\end{pmatrix}\xi=0 \mbox{ if } \displaystyle \sum_{i=1}^{n} \bar y_i = n - s,
\\
\begin{pmatrix}
e_i,0
\end{pmatrix}\xi=0, i \in a_{00}(\bar x,\bar y) \cup a_{01}(\bar x,\bar y),\\
\begin{pmatrix}
0,e_i
\end{pmatrix}\xi=0, i \in a_{00}(\bar x,\bar y) \cup a_{10}(\bar x,\bar y)
\end{array}
\right.\right\}.
\]


\begin{definition}[Nondegenerate T-stationary point, \cite{laemmel:reform}]
A T-stationary point $(\bar x,\bar y)$ of $\mathcal{R}$ with multipliers $(\bar \lambda, \bar \mu, \bar \sigma, \bar \varrho)$ is called nondegenerate if

NDT1: MPOC-LICQ holds at $(\bar x,\bar y)$,

NDT2: $\bar \mu_{1,q}>0$, $q \in Q_0\left(\bar x\right)$, $\bar \mu_{2,i}>0$, $i \in \mathcal{E}\left(\bar y\right)$, and $\bar \mu_3>0$ if  $\sum\limits_{i=1}^{n} \bar  y_i =n-s$,

NDT3: $\bar\varrho_{1,i}\ne 0$ and $\bar\varrho_{2,i}< 0$, $i\in a_{00}\left(\bar x,\bar y\right)$,

NDT4: the matrix $D^2 L^{\mathcal{R}}(\bar x,\bar y)\restriction_{\mathcal{T}^\mathcal{R}_{(\bar x,\bar y)}}$ is nonsingular.

\noindent
For a nondegenerate T-stationary point we eventually use an additional condition:
%\item [] NDT5: if $a_{00}\left(\bar x,\bar y\right)\not = \emptyset$, then $\bar \sigma_{1,i_{01}}\ne 0$ for all $i_{01}\in a_{01}(\bar x, \bar y)$.

NDT6: $\bar \sigma_{1,i}\ne 0$, $i\in a_{01}(\bar x, \bar y)$.
\end{definition}

\begin{definition}[T-index, \cite{laemmel:reform}]
Let $(\bar x,\bar y)$ be a nondegenerate T-stationary point of $\mathcal{R}$ with unique multipliers $\left(\bar \lambda,\bar \mu, \bar \sigma,\bar \varrho\right)$. The number of negative eigenvalues of the matrix $D^2 L^{\mathcal{R}}(\bar x,\bar y)\restriction_{\mathcal{T}^\mathcal{R}_{(\bar x,\bar y)}}$ is called its quadratic index ($QI$). The cardinality of $a_{00}\left(\bar x,\bar y\right)$ is called the biactive index ($BI$) of $(\bar x,\bar y)$. We define the T-index ($TI$) as the sum of both, i.\,e. $TI=QI+BI$.
\end{definition}

Let us now regularize the orthogonality type constraints in $\mathcal{R}$ by using the Scholte's idea, cf. \cite{scholtes:2001}: 
\[
     \begin{array}{rl}
    \displaystyle \mathcal{S}(t): \quad \min_{x,y} \,\, f(x) +c^Ty\quad \mbox{s.\,t.} 
   &h(x)=0, \quad g(x)\ge 0, \quad\displaystyle \sum_{i=1}^{n} y_i \geq  n - s, \\
   & -t\le x_i y_i \le t, \quad 0 \leq y_i \leq 1+\varepsilon,  \quad 
         i=1, \ldots, n,
   \end{array}
\]
where $t>0$. 
%Sometimes, we write $S(t)$ if the dependence on $t$ is highlighted. 
Note that $\mathcal{S}$ from above falls into the scope of nonlinear programming, i.e. just smooth equality and inequality constraints are present. The notation for the sets %$a_{00}\left(x, y\right)$, $a_{01}\left(x, y\right)$, $a_{10}\left(x, y\right)$, 
$Q_0(x)$ and $\mathcal{E}(y)$, which were used for $\mathcal{R}$, will be used here again.
Furthermore, we define for a feasible point $\left( x, y\right)$ of $\mathcal{S}$ the index set of vanishing $y$-components as well as the index sets of active relaxed orthogonality type constraints:
\[
\mathcal{N}( y)=\left\{i\, \left\vert\,  y_i=0\right.\right\},
\quad
\mathcal{H}^{\ge}\left(x, y\right)=\left\{i\,\left\vert \,x_i  y_i=-t\right.\right\}, \mathcal{H}^{\le}\left( x, y\right)=\left\{i\,\left\vert \, x_i  y_i=t\right.\right\}.
\]
We also eventually use the following index sets:
\[
\mathcal{H}\left(x, y\right)=\mathcal{H}^\geq\left(x, y\right) \cup \mathcal{H}^\leq\left( x, y\right), \quad 
\mathcal{O}\left( x, y\right)=\left(\mathcal{E}\left( y\right)\cup \mathcal{N}\left(y\right)\cup \mathcal{H}\left( x, y\right)\right)^c.
\]


\begin{definition}[LICQ]
We say that a feasible point $(x, y)$ of $\mathcal{S}$ satisfies the linear independence constraint qualification (LICQ) if the following vectors are linearly independent:
\[
\begin{array}{c}
      \begin{pmatrix}
\nabla h_p(x)\\0
\end{pmatrix}, p \in P, \quad 
\begin{pmatrix}
\nabla g_q(x)\\0
\end{pmatrix}, q \in Q_0(x), \quad  
\begin{pmatrix}
0\\
e_i
\end{pmatrix},i\in \mathcal{E}(y),
\\ \begin{pmatrix}
0\\
e
\end{pmatrix}
\mbox{ if } \sum\limits_{i=1}^{n} y_i = n - s, \quad
\begin{pmatrix}
y_i e_i\\
x_i e_i
\end{pmatrix}, i \in \mathcal{H}\left(x,y\right), \quad 
\begin{pmatrix}
0\\
e_i
\end{pmatrix}, i \in \mathcal{N}(y).
\end{array}
\]
\end{definition}

\begin{definition}[Karush-Kuhn-Tucker point]
    A feasible point $(x, y)$ of $\mathcal{S}$ is called Kurush-Kuhn-Tucker if there exist multipliers 
\[
\lambda_p, p \in P,
 \mu_{1,q}, q\in Q_0( x), \mu_{2,i},i \in \mathcal{E}( y), \mu_3,
\eta^\ge_i, \eta^\le_i, \nu_i, i\in\left\{1,\ldots,n\right\},
\]
such that the following conditions hold:
\begin{equation}
   \label{eq:kkt-1} 
   \begin{array}{rcl}
  \begin{pmatrix}
   \nabla f( x)\\
   c
  \end{pmatrix}&=& \displaystyle \sum\limits_{p \in P} \lambda_p 
  \begin{pmatrix}
  \nabla h_p( x)\\
  0
  \end{pmatrix}+
    \sum\limits_{q \in Q_0( x)} \mu_{1,q} 
    \begin{pmatrix}
    \nabla g_q( x)\\
    0
    \end{pmatrix}
   - \sum\limits_{i\in\mathcal{E}( y)}  \mu_{2,i} \begin{pmatrix}
    0\\
     e_i
\end{pmatrix}+
 \mu_3 \begin{pmatrix}
0\\
e
\end{pmatrix} \\ 
    && \displaystyle
+ \sum\limits_{i\in\mathcal{H}^\ge( x,  y)}  \eta^\ge_{i} \begin{pmatrix}
    y_ie_i\\
   x_ie_i
\end{pmatrix}
-\sum\limits_{i\in\mathcal{H}^\le( x,  y)}  \eta^\le_{i} \begin{pmatrix}
    y_ie_i\\
    x_ie_i
\end{pmatrix}
+
    \sum\limits_{i\in\mathcal{N}( y)}  \nu_{i} \begin{pmatrix}
    0\\
    e_i
\end{pmatrix},
\end{array}
\end{equation}
\begin{equation}
   \label{eq:kkt-2}  \mu_{1,q} \ge 0,q\in Q_0\left( x\right),
    \mu_{2,i} \ge 0, i\in \mathcal{E}(y),
    \mu_3\ge 0, \mu_3\left(
   \sum\limits_{i=1}^{n}  y_i -(n-s)\right)=0,
\end{equation}
\begin{equation}
   \label{eq:kkt-3} 
  \eta^\ge_i\ge 0,i \in \mathcal{H}^\ge( x,  y), \eta^\le_i\ge 0,i \in \mathcal{H}^\le( x,  y), \nu_i\ge 0, i \in \mathcal{N}( y).
\end{equation}
\end{definition}

We again define the Lagrange function as

\[
        \begin{array}{rcl}
        L^\mathcal{S}(x,y)&=& \displaystyle
   f(x)+c^Ty
       - \sum\limits_{p \in P} \lambda_p 
  h_p(x)-
    \sum\limits_{q \in Q_0(x)} \mu_{1,q} 
    g_q(x)
      \\&& \displaystyle +\sum\limits_{i\in\mathcal{E}(y)}
   \mu_{2,i}
    \left(y_i - (1+\varepsilon)\right)
 -\mu_3\left(\sum\limits_{i=1}^n y_i - (n-s)\right)  \\ 
    && \displaystyle
- \sum\limits_{i\in\mathcal{H}^\ge( x,  y)}  \eta^\ge_{i}
    \left(x_iy_i +t \right)
+\sum\limits_{i\in\mathcal{H}^\le( x,  y)}  \eta^\le_{i}
    \left(x_iy_i-t\right)
-
    \sum\limits_{i\in\mathcal{N}( y)}  \nu_{i}
    y_i.
\end{array}
\]
The tangent space is given by

\[
    \mathcal{T}^\mathcal{S}_{(x,y)} =\left\{
\xi \in \R^{2n}\,\left\vert\, \begin{array}{l} \begin{pmatrix}
Dh_p( x),0\end{pmatrix} \xi=0, p \in P, 
\begin{pmatrix}
Dg_q( x),0\end{pmatrix}\xi=0,q \in Q_0( x),\\ \displaystyle
\begin{pmatrix}
0,e_i
\end{pmatrix}\xi=0, i\in \mathcal{E}(y),
\begin{pmatrix}
0,e
\end{pmatrix}\xi=0 \mbox{ if } \sum_{i=1}^{n} y_i = n - s,\\
\begin{pmatrix}
y_ie_i,x_ie_i
\end{pmatrix}\xi=0, i \in \mathcal{H}\left(x,y\right), 
%\begin{pmatrix} -y_ie_i&-x_ie_i \end{pmatrix}\xi=0, i \in \mathcal{H}^\le\left(x,y\right),\\
\begin{pmatrix}
    0,e_i
\end{pmatrix}\xi=0, i \in \mathcal{N}(y)
\end{array}
\right.\right\}.
\]


\begin{definition}[Nondegenerate Karush-Kuhn-Tucker point]
A Karush-Kuhn-Tucker point $(x, y)$ of $\mathcal{S}$ with multipliers $(\lambda, \mu, \eta, \nu)$
is called nondegenerate if 

ND1: LICQ holds at $( x, y)$,

ND2: $ \mu_{1,q}>0$, $q \in Q_0\left(x\right)$, $ \mu_{2,i}>0$, $i \in \mathcal{E}\left(y\right)$,
    $\eta^\ge_i>0$, $i \in \mathcal{H}^\ge(x,y)$,
    $\eta^\le_i>0$, $i \in \mathcal{H}^\le(x,y)$,
    $\nu_i >0$, $i \in \mathcal{N}(y)$, and $ \mu_3>0$ if  $\sum\limits_{i=1}^{n} y_i =n-s$,

ND3: the matrix $D^2 L^\mathcal{S}(x,y) \restriction_{\mathcal{T}^\mathcal{S}_{(x,y)}}$ is nonsingular.
\end{definition}

\begin{definition}[Quadratic index]
Let $(x,y)$ be a Karush-Kuhn-Tucker point of $\mathcal{S}$ with unique multipliers $(\lambda, \mu, \eta, \nu)$.
The  number of negative eigenvalues of the matrix $D^2 L^\mathcal{S}(x,y)\restriction_{\mathcal{T}^\mathcal{S}_{(x,y)}}$ is called its quadratic index ($QI$).
\end{definition}

From the proof of Theorem \ref{thm:regul} in \cite{laemmel:mpoc} also the convergence of the corresponding multipliers can be deduced.


\begin{remark}[Convergence of multipliers]
\label{rem:multipliers}
 Let $\left(\lambda^t,\mu^t,\eta^t,\nu^t\right)$ be the multipliers of the Karush-Kuhn-Tucker points $\left(x^{t},y^{t}\right)$ of $\mathcal{S}$ and $\left(\bar \lambda,\bar \mu,\bar \sigma, \bar \varrho\right)$ of the T-stationary point $\left(\bar x, \bar y\right)$ of $\mathcal{R}$ as in Theorem \ref{thm:regul}. Due to MPOC-LICQ at $\left(\bar x, \bar y\right)$, we have: 

a) $\lim\limits_{t \to 0} \lambda^t=\bar \lambda$,
    $\lim\limits_{t \to 0} \mu^t=\bar \mu$,

b) $\lim\limits_{t \to 0} \left(\eta_{i}^{\ge,t}-\eta_{i}^{\le,t}\right)y_{i}^t=\bar \sigma_{1,i}$, $i \in a_{01}\left(\bar x, \bar y\right)$,

 c) $\lim\limits_{t \to 0} \nu_{i}^{t}+ \left(\eta_{i}^{\ge,t}-\eta_{i}^{\le,t}\right)x_{i}^t=\bar \sigma_{2,i}$, $i \in a_{10}\left(\bar x, \bar y\right)$,

d) $\lim\limits_{t \to 0} \left(\eta_{i}^{\ge,t}-\eta_{i}^{\le,t}\right)y_{i}^t=\bar \varrho_{1,i}$, $\lim\limits_{t \to 0} \nu_{i}^{t}+ \left(\eta_{i}^{\ge,t}-\eta_{i}^{\le,t}\right)x_{i}^t=\bar \varrho_{2,i}$, $i \in a_{00}\left(\bar x, \bar y\right)$.
\end{remark}

