\end{pmatrix}\xi=0, i \in a_{01}(\bar x,\bar y)\cup a_{10}(\bar x,\bar y)
\end{array}
\right.\right\}.
\]
Let $\left\{\lambda^+_1,\ldots,\lambda^+_{k^+}\right\}$ be the positive 
eigenvalues of 
$D^2 L^\mathcal{S}\left( x^t, y^t\right)\restriction_{\mathcal{T}^\mathcal{R}_{\left(\bar x,\bar y\right)}}$ with corresponding eigenvectors 
$\left\{\xi^+_1,\ldots,\xi^+_{k^+}\right\}$.
Hence, for all $k=1,\ldots, k^+$:
\[
{\xi^+_k}^T D^2 L^\mathcal{S}\left( x^t, y^t\right)\xi^+_k>0.
\]
We rewrite the tangent space as follows:
\[
    \mathcal{T}^\mathcal{R}_{\left(\bar x,\bar y\right)}=\left\{
\xi \in \R^{2n}\,\left\vert\, \begin{array}{l} \begin{pmatrix}

Dh_p(\bar x),0\end{pmatrix} \xi=0, p \in P, 
\begin{pmatrix}
